#!/usr/bin/env python3
"""Check the synchroniser's RTL against the fixed-point model, bit for bit.

    python scripts/cosimulate_sync.py --bits 12 --vectors 512

The Python model in :mod:`qnet_qkd.hardware.fixed_point` is the golden
reference: it is what the word-length sweep was measured with, so it is what
the hardware has to reproduce.  This script fits the same ridge the phase-5
study fits, quantises it, writes the coefficient ROM and a batch of real
feature windows as hex, runs ``rtl/sync_predictor.v`` under Icarus Verilog, and
compares every returned integer against the model's.

A single mismatched LSB fails the run.  There is no tolerance here on purpose —
a tolerance would hide exactly the class of bug this is built to catch, which is
a rounding or sign-extension mistake that shows up on one vector in a thousand.
"""
from __future__ import annotations

import argparse
import subprocess
import sys
from pathlib import Path

import numpy as np

REPO_ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(REPO_ROOT))
sys.path.insert(0, str(REPO_ROOT / "scripts"))

from task5 import LINK, SYNC_TRAIN_SEEDS, make_gate, make_timing_trajectories  # noqa: E402
from qnet_qkd.hardware.fixed_point import quantise_ridge  # noqa: E402
from qnet_qkd.qkd.timing import (build_sync_dataset,  # noqa: E402
                                       fit_sync_predictor)


def _two_complement(value: int, width: int) -> str:
    """``value`` as a fixed-width hex literal, the way ``$readmemh`` reads it."""
    return format(int(value) & ((1 << width) - 1), f"0{(width + 3) // 4}x")


def write_vectors(directory: Path, model, features: np.ndarray) -> dict:
    """Emit the ROM, the intercept, the stimulus and the elaboration header."""
    word = model.coefficient_format.word_bits
    accumulator = model.accumulator_format.word_bits
    taps = len(model.coefficients)
    shift = (model.input_format.fraction_bits
             + model.coefficient_format.fraction_bits
             - model.accumulator_format.fraction_bits)
    right, left = max(shift, 0), max(-shift, 0)

    # The accumulator has to sit above the widest intermediate — the scaled
    # product — with room for the sum of ``taps`` of them.  Sizing the guard
    # here rather than in the RTL keeps the module free of assumptions about
    # the format it is elaborated with.
    headroom = int(np.ceil(np.log2(max(taps, 2)))) + 2
    guard = max(headroom, 2 * word + left - accumulator + headroom)

    codes = model.input_format.to_integer(features)
    intercept = int(model.accumulator_format.to_integer(model.intercept)[()])

    (directory / "coefficients.hex").write_text(
        "\n".join(_two_complement(code, word)
                  for code in model.coefficient_codes) + "\n")
    (directory / "intercept.hex").write_text(
        _two_complement(intercept, accumulator) + "\n")
    (directory / "stimulus.hex").write_text(
        "\n".join(_two_complement(code, word) for code in codes.reshape(-1)) + "\n")
    (directory / "sync_params.vh").write_text(
        "// Generated by scripts/cosimulate_sync.py — do not edit.\n"
        "`ifndef SYNC_PARAMS_VH\n`define SYNC_PARAMS_VH\n"
        f"`define SP_WORD    {word}\n"
        f"`define SP_ACC_W   {accumulator}\n"
        f"`define SP_TAPS    {taps}\n"
        f"`define SP_RSHIFT  {right}\n"
        f"`define SP_LSHIFT  {left}\n"
        f"`define SP_GUARD   {guard}\n"
        f"`define SP_VECTORS {len(codes)}\n"
        "`endif\n")

    return {"word": word, "accumulator": accumulator, "shift": shift,
            "guard": guard, "taps": taps, "vectors": len(codes)}


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--bits", type=int, default=12)
    parser.add_argument("--vectors", type=int, default=512)
    parser.add_argument("--rounding", default="round", choices=["round", "truncate"])
    parser.add_argument("--build", type=Path, default=Path("runs/hardware/rtl"))
    parser.add_argument("--rtl", type=Path, default=Path("rtl"))
    parser.add_argument("--seed", type=int, default=0)
    args = parser.parse_args()

    if args.rounding == "truncate":
        raise SystemExit(
            "the RTL implements round-half-away-from-zero only; "
            "truncation is measured in the sweep, not synthesised here")

    build = (REPO_ROOT / args.build).resolve()
    build.mkdir(parents=True, exist_ok=True)

    gate = make_gate()
    trajectories = make_timing_trajectories(SYNC_TRAIN_SEEDS, LINK.length_km)
    features, targets, _, _ = build_sync_dataset(trajectories, gate)
    learned = fit_sync_predictor(features, targets)
    model = quantise_ridge(learned.model, features, word_bits=args.bits,
                           rounding=args.rounding)
    print(f"[cosim] ridge {args.bits}b — entrada {model.input_format.describe()}, "
          f"coeficientes {model.coefficient_format.describe()}, "
          f"acumulador {model.accumulator_format.describe()}")

    generator = np.random.default_rng(args.seed)
    chosen = generator.choice(len(features), size=min(args.vectors, len(features)),
                              replace=False)
    sample = features[np.sort(chosen)]

    shape = write_vectors(build, model, sample)
    print(f"[cosim] {shape['vectors']} vetores, {shape['taps']} taps, "
          f"deslocamento {shape['shift']:+d}, guarda {shape['guard']} bits")

    sources = [str((REPO_ROOT / args.rtl / name).resolve())
               for name in ("sync_predictor.v", "tb_sync_predictor.v")]
    compile_result = subprocess.run(
        ["iverilog", "-g2012", "-I", str(build), "-o", "simulation", *sources],
        cwd=build, capture_output=True, text=True)
    if compile_result.returncode != 0:
        print(compile_result.stdout)
        print(compile_result.stderr)
        raise SystemExit("iverilog falhou")

    run_result = subprocess.run(["vvp", "simulation"], cwd=build,
                                capture_output=True, text=True)
    print(run_result.stdout.strip())
    if run_result.returncode != 0:
        print(run_result.stderr)
        raise SystemExit("vvp falhou")

    emitted = np.loadtxt(build / "rtl_result.txt", dtype=np.int64)
    expected = model.accumulator_format.to_integer(model.predict(sample))
    if emitted.shape != expected.shape:
        raise SystemExit(f"o RTL devolveu {emitted.shape} valores, "
                         f"o modelo {expected.shape}")

    mismatches = int(np.count_nonzero(emitted != expected))
    worst = int(np.max(np.abs(emitted - expected))) if len(emitted) else 0
    print(f"[cosim] {len(emitted)} vetores, {mismatches} divergências, "
          f"pior diferença {worst} LSB")

    if mismatches:
        index = int(np.argmax(np.abs(emitted - expected)))
        print(f"  primeiro exemplo: vetor {index}, "
              f"RTL {emitted[index]}, modelo {expected[index]}")
        return 1

    # The predictor's output is an increment in units of ``learned.scale``, so
    # one LSB of the accumulator is that many seconds — the figure that decides
    # whether the word length is adequate, since the loop's residual is tens of
    # picoseconds.
    lsb_s = model.accumulator_format.resolution * learned.scale
    print(f"[cosim] equivalência bit a bit; 1 LSB = {lsb_s * 1e12:.4f} ps "
          f"contra um resíduo de dezenas de ps")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
